// S-ynapse Security Worker — runs at the Cloudflare Worker edge.
// Provides: rate limiting, CSP headers, HTTP→HTTPS redirect, admin path blocking.
// This is a dynamic security layer that runs before Cloudflare Pages serves the static assets.
// Note: _headers file (generated by build.js → generateSecurityHeaders) provides a parallel
// static security layer. Changes here and in _headers must be kept in sync.

const rateLimitMap = new Map();

// Hardcoded security config — should be aligned with security.json for consistency.
// In production, consider moving these to Worker secrets or environment variables.
const CONFIG = {
  rateLimiting: {
    maxRequests: 100,
    windowMs: 60000,
    blockDuration: 300000,
  },
  csp: {
    directives: {
      "default-src": ["'self'"],
      "script-src": ["'self'", "'unsafe-inline'", "https://cdn.jsdelivr.net"],
      "style-src": ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
      "img-src": ["'self'", "data:", "https:"],
      "font-src": ["'self'", "https://fonts.gstatic.com"],
      "object-src": ["'none'"],
      "frame-src": ["'none'"],
    }
  }
};

async function handleRequest(request, env) {
  const url = new URL(request.url);
  // Skip rate limiting when clientIP is null (not behind Cloudflare — e.g. local dev)
  // This prevents all local requests from sharing a single 'unknown' rate limit bucket.
  const clientIP = request.headers.get('CF-Connecting-IP');

  // HTTP→HTTPS redirect in production only (local dev uses HTTP)
  if (url.protocol !== 'https:' && env.ENVIRONMENT === 'production') {
    url.protocol = 'https:';
    return Response.redirect(url.toString(), 301);
  }

  // CSP violation report endpoint — accepts POST from browsers and logs the report
  if (url.pathname === '/csp-report' && request.method === 'POST') {
    try {
      const report = await request.json();
      console.log('CSP Violation:', JSON.stringify(report));
    } catch (e) {
      console.warn('CSP report parse failed:', e.message);
    }
    return new Response('ok', { status: 200 });
  }

  // Rate limiting — sliding window per client IP.
  // Blocked clients receive 429 for blockDuration ms.
  // Map is cleaned when size exceeds 5000 entries (lazy eviction).
  if (CONFIG.rateLimiting && clientIP) {
    const now = Date.now();
    const windowMs = CONFIG.rateLimiting.windowMs;
    const maxRequests = CONFIG.rateLimiting.maxRequests;
    const blockDuration = CONFIG.rateLimiting.blockDuration;

    let entry = rateLimitMap.get(clientIP);
    if (entry) {
      if (entry.blockedUntil && now < entry.blockedUntil) {
        return new Response('Too Many Requests', { status: 429 });
      }
      entry.hits = entry.hits.filter(t => now - t < windowMs);
      if (entry.hits.length >= maxRequests) {
        entry.blockedUntil = now + blockDuration;
        return new Response('Too Many Requests', { status: 429 });
      }
      entry.hits.push(now);
    } else {
      rateLimitMap.set(clientIP, { hits: [now] });
    }
    if (rateLimitMap.size > 5000) {
      const cutoff = now - windowMs;
      for (const [ip, data] of rateLimitMap) {
        if (data.blockedUntil && data.blockedUntil < now) {
          rateLimitMap.delete(ip);
        } else {
          data.hits = data.hits.filter(t => now - t < windowMs);
          if (data.hits.length === 0) rateLimitMap.delete(ip);
        }
      }
    }
  }

  // Block admin paths at the edge before they reach static assets
  if (url.pathname.startsWith('/admin/')) {
    return new Response('Forbidden', { status: 403 });
  }

  // Fetch the static asset from Cloudflare Pages
  const response = await env.ASSETS.fetch(request);

  // Attach security headers to the response
  const headers = new Headers(response.headers);

  // CSP header from hardcoded config (must match security.json → _headers)
  const cspDirectives = [];
  for (const [key, vals] of Object.entries(CONFIG.csp.directives)) {
    if (Array.isArray(vals) && vals.length > 0) {
      cspDirectives.push(`${key} ${vals.join(' ')}`);
    }
  }
  if (cspDirectives.length > 0) {
    headers.set('Content-Security-Policy', cspDirectives.join('; '));
  }

  // Standard security headers (same as _headers)
  headers.set('X-Frame-Options', 'DENY');
  headers.set('X-Content-Type-Options', 'nosniff');
  headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  headers.set('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  headers.set('X-XSS-Protection', '1; mode=block');

  headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default {
  fetch: handleRequest,
};
